    "createdAt": "2026-02-07T23:40:39+00:00",
    "categoryName": "Musical Theatre & Cinema",
    "seoTitle": "Opera Scenic Design History: From Baroque to Contemporary Stage",
    "seoDescription": "Trace opera scenic design from Renaissance origins through modern staging practices, with lessons on scale, composition, transition logic, and audience experience.",
    "seoKeywords": "opera scenic design, opera history, theatrical design, performance design, Teatro San Cassiano, Renaissance theatre, visual storytelling",
    "featured": false,
